def count_divisors(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i*i != n:
                count += 1
    return count

def is_exotic(n):
    # n is exotic if the number of n-good functions is twice an odd integer.
    # The number of n-good functions is 2 * d(n).
    # So 2 * d(n) = 2 * (2k+1) => d(n) = 2k+1 (odd).
    # d(n) is odd iff n is a perfect square.
    return count_divisors(n) % 2 == 1

exotic_integers = []
n = 1
while len(exotic_integers) < 132:
    if is_exotic(n):
        exotic_integers.append(n)
    n += 1

print(f"The {len(exotic_integers)}th exotic integer is {exotic_integers[-1]}")
